  {"subject": "English", "year": 2063, "question": "Choose the option that correctly completes: 'If I ___ you, I would apologise.'", "options": ["am", "was", "were", "be"], "correctIndex": 2, "explanation": "The subjunctive mood uses 'were' for all persons in hypothetical conditionals."},
  {"subject": "English", "year": 2064, "question": "Choose the option that correctly completes: 'Each of the candidates ___ given a form.'", "options": ["were", "was", "have been", "are"], "correctIndex": 1, "explanation": "'Each' is singular and takes a singular verb."},
