  {"subject": "English", "year": 2067, "question": "Choose the option that correctly completes: 'By the time you arrive, we ___ the meeting.'", "options": ["will start", "will have started", "started", "start"], "correctIndex": 1, "explanation": "Future perfect tense expresses an action completed before another future action."},
