  {"subject": "English", "year": 2003, "question": "Identify the figure of speech: 'The wind whispered through the trees.'", "options": ["Simile", "Personification", "Hyperbole", "Metonymy"], "correctIndex": 1, "explanation": "Personification attributes human qualities (whispering) to non-human objects (wind)."},
  {"subject": "English", "year": 2004, "question": "Identify the figure of speech: 'Time is a thief.'", "options": ["Simile", "Metaphor", "Alliteration", "Onomatopoeia"], "correctIndex": 1, "explanation": "Metaphor compares two things without using 'like' or 'as'."},
  {"subject": "English", "year": 2005, "question": "Identify the figure of speech: 'She runs like the wind.'", "options": ["Simile", "Metaphor", "Irony", "Oxymoron"], "correctIndex": 0, "explanation": "Simile uses 'like' or 'as' to compare two things."},
  {"subject": "English", "year": 2006, "question": "Identify the figure of speech: 'I have told you a million times.'", "options": ["Understatement", "Hyperbole", "Euphemism", "Metonymy"], "correctIndex": 1, "explanation": "Hyperbole is extreme exaggeration for emphasis."},
  {"subject": "English", "year": 2007, "question": "Identify the figure of speech: 'Peter Piper picked a peck of pickled peppers.'", "options": ["Alliteration", "Assonance", "Personification", "Irony"], "correctIndex": 0, "explanation": "Alliteration repeats initial consonant sounds."},
  {"subject": "English", "year": 2008, "question": "Identify the figure of speech: 'The bees buzzed in the garden.'", "options": ["Simile", "Onomatopoeia", "Metaphor", "Hyperbole"], "correctIndex": 1, "explanation": "Onomatopoeia uses words that imitate sounds."},
  {"subject": "English", "year": 2009, "question": "Identify the figure of speech: 'The fireman's house burned down.'", "options": ["Simile", "Irony", "Metaphor", "Alliteration"], "correctIndex": 1, "explanation": "Irony is when the outcome is opposite to expectations."},
  {"subject": "English", "year": 2078, "question": "Identify the figure of speech: 'The White House announced new policies today.'", "options": ["Metonymy", "Simile", "Hyperbole", "Personification"], "correctIndex": 0, "explanation": "Metonymy substitutes the name of something (White House) for something closely associated with it (the government)."},
  {"subject": "English", "year": 2079, "question": "Identify the figure of speech: 'The crowd of eyes watched the game.'", "options": ["Simile", "Synecdoche", "Hyperbole", "Alliteration"], "correctIndex": 1, "explanation": "Synecdoche uses a part (eyes) to represent the whole (people)."},
  {"subject": "English", "year": 2080, "question": "Identify the figure of speech: 'It was the best of times, it was the worst of times.'", "options": ["Antithesis", "Metaphor", "Euphemism", "Simile"], "correctIndex": 0, "explanation": "Antithesis places two contrasting ideas together for effect."},
  {"subject": "English", "year": 2081, "question": "Identify the figure of speech: 'He passed away peacefully in his sleep.'", "options": ["Hyperbole", "Euphemism", "Metonymy", "Irony"], "correctIndex": 1, "explanation": "Euphemism substitutes a mild expression for a harsh one, such as 'passed away' for 'died'."},
  {"subject": "English", "year": 2082, "question": "Identify the figure of speech: 'This is the beginning of the end.'", "options": ["Oxymoron", "Simile", "Metonymy", "Personification"], "correctIndex": 0, "explanation": "Oxymoron combines contradictory terms, such as 'beginning' and 'end'."},
  {"subject": "English", "year": 2083, "question": "Identify the figure of speech: 'The silence was deafening.'", "options": ["Oxymoron", "Simile", "Hyperbole", "Metonymy"], "correctIndex": 0, "explanation": "Oxymoron joins two contradictory terms, 'silence' and 'deafening'."},
  {"subject": "English", "year": 2084, "question": "Identify the figure of speech: 'Ask not what your country can do for you.'", "options": ["Chiasmus", "Simile", "Hyperbole", "Onomatopoeia"], "correctIndex": 0, "explanation": "Chiasmus reverses the grammatical structure in successive clauses for effect."},
  {"subject": "English", "year": 2085, "question": "Identify the figure of speech: 'The stars danced playfully in the sky.'", "options": ["Simile", "Personification", "Metonymy", "Antithesis"], "correctIndex": 1, "explanation": "Personification gives human actions (dancing) to non-human things (stars)."},

